const ACCOUNT_NAME_RE = new RegExp(ACCOUNT_NAME_PATTERN);

/** 见 [`ACCOUNT_NAME_PATTERN`]。 */
export function accountNameOk(s: string): boolean {
  return ACCOUNT_NAME_RE.test(s);
}

